// A valid :status block is split across HEADERS and CONTINUATION. Only the
// continuation stream ID is wrong. A same-stream positive control decodes it.
#[tokio::test]
async fn false_1_continuation_must_match_stream_id() {
    let mut same_stream = raw_codec! {
        read => [
            0, 0, 1, 1, 0, 0, 0, 0, 1, 0x88,
            0, 0, 0, 9, 4, 0, 0, 0, 1,
        ];
    };
    let headers = same_stream.next().await.unwrap().unwrap();
    match headers {
        frame::Frame::Headers(headers) => {
            assert_eq!(headers.stream_id(), 1);
            assert_eq!(headers.pseudo().status.unwrap(), StatusCode::OK);
        }
        other => panic!("expected HEADERS, got {:?}", other),
    }
    let mut wrong_stream = raw_codec! {
        read => [
            0, 0, 1, 1, 0, 0, 0, 0, 1, 0x88,
            0, 0, 0, 9, 4, 0, 0, 0, 3,
        ];
    };
    let err = wrong_stream.next().await.unwrap().unwrap_err();
    match err {
        proto::Error::GoAway(_, Reason::PROTOCOL_ERROR, proto::Initiator::Library) => {},
        other => panic!("expected library PROTOCOL_ERROR GOAWAY, got {:?}", other),
    }
}

// Exercise the exact signed 31-bit boundary with no large allocations. PING
// provides a barrier proving that reaching MAX itself is accepted before +1.
#[tokio::test]
async fn false_5_connection_window_overflow_is_rejected() {
    let (io, mut peer) = mock::new();
    let driver = async move {
        let (_client, conn) = client::handshake(io).await.unwrap();
        let err = conn.await.unwrap_err();
        assert!(err.is_go_away());
        assert_eq!(err.reason(), Some(Reason::FLOW_CONTROL_ERROR));
    };
    let peer = async move {
        peer.assert_client_handshake().await;
        peer.send_frame(frames::window_update(0, 0x7fff_ffff - 65_535)).await;
        peer.send_frame(frames::ping([7; 8])).await;
        peer.recv_frame(frames::ping([7; 8]).pong()).await;
        peer.send_frame(frames::window_update(0, 1)).await;
        peer.recv_frame(frames::go_away(0).flow_control()).await;
    };
    tokio::time::timeout(Duration::from_secs(5), join(peer, driver)).await.unwrap();
}
''')
